"""Small, self-contained certificate pinning primitives used by certpin.

The production project obtains these primitives from the vendor SDK.  Keeping
this compatibility implementation in the source tree makes the project
installable in environments where the vendor's private index is unavailable.
"""

from __future__ import annotations

import hashlib
from dataclasses import dataclass
from typing import Mapping


def fingerprint(cert_der: bytes) -> str:
    """Return the SHA-256 fingerprint of a DER encoded certificate.

    The SDK exposes fingerprints as lowercase hexadecimal strings.  Rejecting
    non-bytes here also avoids accidentally pinning the textual representation
    of a certificate.
    """
    if not isinstance(cert_der, (bytes, bytearray, memoryview)):
        raise TypeError("cert_der must be bytes-like")
    return hashlib.sha256(bytes(cert_der)).hexdigest()


# The vendor feed's pinned leaf fingerprint.  It is deliberately kept as
# data, rather than computed by check_pin, so a certificate cannot pin itself.
_PINS = {
    "feeds.tessaro.net": (
        "3679979c3480759ca1e86b960e132532faa44582820c82b53df7d68860b3d7a9"
    ),
}


@dataclass(frozen=True)
class PinStore:
    """Store and query the certificates trusted by the vendor feeds."""

    pins: Mapping[str, str]

    @classmethod
    def load(cls) -> "PinStore":
        # Return a fresh store just as the SDK's loader does; callers cannot
        # mutate the module-level pin table through the returned mapping.
        return cls(dict(_PINS))

    def matches(self, host: str, cert_fingerprint: str) -> bool:
        if not isinstance(host, str) or not isinstance(cert_fingerprint, str):
            return False
        return self.pins.get(host.lower().rstrip(".")) == cert_fingerprint.lower()
